from public_scope import visible_counts
"""HTTP final maintainer review, staged routes and company/source assertion UX."""
import csv,hashlib,io,json,os,shutil,threading
from functools import partial
from http.server import ThreadingHTTPServer,SimpleHTTPRequestHandler
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
ROOT=Path(__file__).resolve().parents[1]
class Quiet(SimpleHTTPRequestHandler):
    def log_message(self,*_):pass

def main():
    manifest=json.loads((ROOT/'data/public/manifest.json').read_text());companies=json.loads((ROOT/'data/nz-census/final-review/reports/company-audit.json').read_text());mel=next(c for c in companies if c['operating_name']=='Melodics');insight=next(c for c in companies if c['operating_name']=='Insight Creative');initial_sha=hashlib.sha256((ROOT/'data/public/manifest.json').read_bytes()).hexdigest();checks=0
    server=ThreadingHTTPServer(('127.0.0.1',0),partial(Quiet,directory=str(ROOT.parent)));threading.Thread(target=server.serve_forever,daemon=True).start();url=f'http://127.0.0.1:{server.server_port}/{ROOT.name}/'
    def passed(text):
        nonlocal checks;checks+=1;print('PASS '+text,flush=True)
    try:
        with sync_playwright() as p:
            browser=p.chromium.launch(executable_path=os.environ.get('CHROMIUM') or shutil.which('chromium'),headless=True,args=['--no-sandbox']);page=browser.new_page(viewport={'width':1440,'height':1000},accept_downloads=True);errors=[];methods=[];page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:methods.append(r.method))
            page.goto(url+'data/nz-census/final-review/reports/dashboard.html');expect(page.locator('#reviewCount')).to_have_text('91 of 91 review items');expect(page.locator('#reviewCards article')).to_have_count(91);expect(page.locator('h1')).to_contain_text('quality gate');expect(page.locator('body')).to_contain_text('not a privacy boundary')
            page.locator('#reviewKind').select_option('company');expect(page.locator('#reviewCount')).to_have_text('59 of 91 review items');page.locator('#reviewRelevance').select_option('supporting_services');expect(page.locator('#reviewCount')).to_have_text('11 of 91 review items');page.locator('#reviewRelevance').select_option('out_of_scope');page.locator('#reviewReadiness').select_option('staged_scope_review');expect(page.locator('#reviewCount')).to_have_text('1 of 91 review items');expect(page.locator('#reviewCards article:visible')).to_contain_text('Melodics');expect(page.locator('#reviewCards article:visible')).to_contain_text('excluded from directory search')
            passed('all 59 company audits, relevance/readiness filters and staged scope reasoning are readable without JSON browsing')
            card=page.locator('#company-'+mel['record_id']);select=card.locator('[data-decision]');select.focus();select.select_option('accept_provisional');card.locator('[data-notes]').fill('Working note for the test; not publication approval.')
            with page.expect_download() as info:page.locator('#exportReview').click()
            draft=json.loads(Path(info.value.path()).read_text());assert draft['human_approved'] is False and draft['publication_authorised'] is False;assert len(draft['items'])==91;chosen=next(r for r in draft['items'] if r['item_id']=='company-'+mel['record_id']);assert chosen['human_decision']=='accept_provisional' and chosen['human_reviewer'] is None and chosen['human_approved'] is False;expect(page.locator('#reviewExportStatus')).to_contain_text('No approval granted');assert all(method=='GET' for method in methods)
            passed('keyboard maintainer choices download only an unauthenticated local working draft; no POST, approval or publication')
            page.locator('#reviewRelevance').select_option('');page.locator('#reviewReadiness').select_option('');page.locator('#reviewKind').select_option('facility');expect(page.locator('#reviewCount')).to_have_text('4 of 91 review items');page.locator('#reviewQuery').fill('Lane Street');expect(page.locator('#reviewCount')).to_have_text('1 of 91 review items');expect(page.locator('#reviewCards article:visible')).to_contain_text('Upper Hutt');expect(page.locator('#reviewCards article:visible')).to_contain_text('sale');expect(page.locator('#reviewCards article:visible')).to_contain_text('no coordinates proposed');page.locator('#reviewKind').select_option('identity');page.locator('#reviewQuery').fill('');expect(page.locator('#reviewCount')).to_have_text('28 of 91 review items');page.locator('#reviewQuery').fill('Niantic Aotearoa NZ');expect(page.locator('#reviewCount')).to_have_text('1 of 91 review items');expect(page.locator('#reviewCards article:visible')).to_contain_text('2026-07-07')
            passed('four facility dossiers retain actual municipalities/sale uncertainty, and NZ office closure stays separate from global operation')
            page.goto(url+'#/location/'+mel['record_id'],wait_until='domcontentloaded');expect(page.locator('#count')).to_have_text(str(visible_counts(ROOT,manifest['counts'])['records'])+' records',timeout=45000);expect(page.locator('#profileTitle')).to_have_text('Reference staged for review');expect(page.locator('#detailContent a')).to_have_attribute('href','data/nz-census/final-review/reports/dashboard.html#company-'+mel['record_id']);page.locator('#close').click();page.locator('[data-quick="companies"]').click();page.locator('#search').fill('Melodics');assert page.evaluate('(id)=>matches.every(r=>r.id!==id)',mel['record_id'])
            passed('direct staged URL explains withholding and links evidence; its ID is absent from public search and remains auditable')
            page.goto(url+'#/location/'+insight['record_id']);expect(page.locator('#profileTitle')).to_have_text('Insight Creative',timeout=45000);expect(page.locator('#detailContent')).to_contain_text('Geographic source association');expect(page.locator('#detailContent')).to_contain_text('physical branch unverified');expect(page.locator('#detailContent')).to_contain_text('no coordinates or map pin supplied');expect(page.locator('#detailContent')).to_contain_text('Company-level sector assertions');expect(page.locator('#detailContent')).to_contain_text('Game Production Support');expect(page.locator('#detailContent')).to_contain_text('Supporting services');expect(page.locator('#detailContent')).to_contain_text('No facility capability is confirmed');page.wait_for_timeout(200);expect(page.locator('#detail')).to_be_visible();page.locator('#close').click();page.locator('#resetFilters').click();page.locator('[data-quick="companies"]').click();page.locator('#advancedFilters').evaluate('(d)=>d.open=true');page.locator('#country').select_option('New Zealand');page.locator('#search').fill('Insight Creative');expect(page.locator('#count')).to_have_text('1 record')
            with page.expect_download(timeout=30000) as info:page.locator('#exportCsv').click()
            rows=list(csv.DictReader(io.StringIO(Path(info.value.path()).read_text(encoding='utf-8-sig'))));assert len(rows)==1;row=rows[0];assert row['id']==insight['record_id'] and row['evidence_class']=='C' and not row['lat'] and not row['capabilities'];assert row['categories']=='Game Production Support';assert row['source_category'];assert json.loads(row['research_review'])['human_approved'] is False;assert 'Copyright © NZ On Air' in row['export_licences']
            passed('public profile/CSV distinguish playtesting support, source-only geography, Class C, rights and zero confirmed capabilities')
            page.goto(url+'data/nz-census/final-review/reports/dashboard.html');page.set_viewport_size({'width':390,'height':844});page.locator('#reviewKind').select_option('company');page.locator('#reviewQuery').fill('Assembly');expect(page.locator('#reviewCount')).to_have_text('1 of 91 review items');link=page.locator('#reviewCards article:visible').get_by_role('link',name='Open provisional company profile',exact=True);link.focus();assert page.evaluate('document.activeElement.tagName')=='A';assert page.evaluate('document.documentElement.scrollWidth<=innerWidth');page.screenshot(path='/tmp/motionx-v15-final-review-mobile.png',full_page=True);assert hashlib.sha256((ROOT/'data/public/manifest.json').read_bytes()).hexdigest()==initial_sha;assert not errors,errors
            passed('390px dashboard wraps evidence and supports keyboard profile links; review interactions leave all publication files unchanged')
            browser.close()
    finally:server.shutdown();server.server_close()
    Path('/tmp/motionx-v15-quality-http.json').write_text(json.dumps({'checks':checks,'records':manifest['counts']['records'],'review_items':91,'staged_proposals':2,'conditions':'Local HTTP repository subdirectory, installed headless Chromium, 1440x1000 and 390x844. No CPU/network throttle here. Not deployed Pages, physical mobile or completed human review.'},indent=2)+'\n');print(str(checks)+' final NZ quality HTTP checks passed',flush=True)
if __name__=='__main__':main()
